<?php
require_once __DIR__.'/inc/functions.php';require_once __DIR__.'/inc/ModuleProjectAccess.php';require_once __DIR__.'/inc/InventoryVersions.php';require_once __DIR__.'/inc/ProjectBackups.php';
header('Cache-Control: no-store');if(!isUser())redirect('/?action=login');$project=ModuleProjectAccess::select($_GET['project']??$_SESSION['project_id']??'');if(!canAccessManagement()||(!isMainAdmin()&&!isProjectAdmin()))AccessControl::deny();$pid=$project['id'];$error='';$message='';$preview=null;
try{
    if(isset($_GET['download'])){$data=ProjectBackups::read($pid,$_GET['download']);header('Content-Type: application/json');header('Content-Disposition: attachment; filename="project-backup-'.$_GET['download'].'.json"');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){RequestSecurity::enforce();$action=$_POST['action']??'';
        if($action==='resume'){require_once __DIR__.'/inc/ProjectOnboarding.php';ProjectOnboarding::mutate($pid,function(&$p){unset($p['settings']['backup_restore_paused']);});$message='توقف صف‌های موجود رفع شد؛ اتصال ERP و وردپرس را جداگانه از تنظیمات فعال کنید.';}
        elseif($action==='create'){$id=ProjectBackups::capture($pid);$message='بک‌آپ ایجاد شد: '.$id;}
        elseif($action==='upload'){if(($_FILES['backup_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file($_FILES['backup_file']['tmp_name']))throw new RuntimeException('فایل بک‌آپ کامل دریافت نشد.');$id=ProjectBackups::import($pid,file_get_contents($_FILES['backup_file']['tmp_name']));$data=ProjectBackups::read($pid,$id);$preview=['id'=>$id,'products'=>count($data['products']),'files'=>count($data['files'])];$_SESSION['backup_preview']=['project'=>$pid,'id'=>$id,'hash'=>hash('sha256',json_encode($data)),'expires'=>time()+900];}
        elseif($action==='preview'){$id=$_POST['backup']??'';$data=ProjectBackups::read($pid,$id);$preview=['id'=>$id,'products'=>count($data['products']),'files'=>count($data['files'])];$_SESSION['backup_preview']=['project'=>$pid,'id'=>$id,'hash'=>hash('sha256',json_encode($data)),'expires'=>time()+900];}
        elseif($action==='restore'){$v=$_SESSION['backup_preview']??[];if(($v['project']??'')!==$pid||($v['id']??'')!==($_POST['backup']??'')||($v['expires']??0)<time())throw new RuntimeException('ابتدا پیش‌نمایش تازه بگیرید.');$data=ProjectBackups::read($pid,$v['id']);if(!hash_equals($v['hash'],hash('sha256',json_encode($data))))throw new RuntimeException('بک‌آپ تغییر کرده است.');$id=ProjectBackups::restore($project,$data);unset($_SESSION['backup_preview']);$message='بازیابی انجام شد. نسخهٔ ایمنی: '.$id.'؛ همگام‌سازی خودکار متوقف شد.';}
    }
}catch(Throwable $e){http_response_code(422);$error=$e instanceof RuntimeException?$e->getMessage():'بک‌آپ معتبر نیست یا عملیات ناموفق بود.';}
function bk_h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}$status=ProjectBackups::status($pid);
$versions=ProjectBackups::listing($pid);
?><!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>بک‌آپ پروژه</title><link rel="stylesheet" href="/panel/assets/workspace-shell.css"><link rel="stylesheet" href="/panel/assets/backup-workspace.css"></head><body class="workspace-page"><main class="workspace-shell backup-workspace">
<header class="bk-header"><a href="/panel/workspace.php">← انتخاب میزکار</a><span>مدیریت داده‌های پروژه</span></header>
<div class="bk-hero"><div><span class="bk-eyebrow">نسخه‌های امن، بازیابی با اطمینان</span><h1>بک‌آپ پروژه</h1><p><?=bk_h($project['name'])?> · کتابخانهٔ محصولات و تصاویر محلی</p></div><form method="post"><button class="bk-primary" name="action" value="create">＋ ساخت بک‌آپ دستی</button></form></div>
<?php if($message):?><p class="bk-notice success" role="status"><?=bk_h($message)?></p><?php endif;?><?php if($error):?><p class="bk-notice error" role="alert"><?=bk_h($error)?></p><?php endif;?>
<div class="bk-metrics"><article><span>نسخه‌های ذخیره‌شده</span><strong><?=count($versions)?></strong><small>مخصوص همین پروژه</small></article><article><span>آخرین بک‌آپ هفتگی موفق</span><strong><?=!empty($status['last_success'])?bk_h(formatPersianDate($status['last_success'],'Y/m/d H:i')):'هنوز اجرا نشده'?></strong><small>اجرای زمان‌بندی‌شده به Cron سرور نیاز دارد.</small></article><article><span>وضعیت اجرای هفتگی</span><strong><?=!empty($status['error'])?'نیازمند بررسی':'خطایی ثبت نشده'?></strong><small><?=bk_h($status['error']??'وضعیت پس از اجرای Cron به‌روز می‌شود.')?></small></article></div>
<?php if(!empty($project['settings']['backup_restore_paused'])):?><section class="bk-notice warning"><h2>ارسال‌های خودکار متوقف‌اند</h2><p>پس از بازیابی، ابتدا محصولات و تصاویر را بررسی کنید. اتصال ERP و وردپرس باید جداگانه از تنظیمات فعال شود.</p><form method="post"><button name="action" value="resume">بررسی کردم؛ ادامهٔ صف‌های موجود</button></form></section><?php endif;?>
<?php if($preview):?><section class="bk-preview"><span class="bk-eyebrow">مرحلهٔ ۲ از ۲ · تأیید شما لازم است</span><h2>پیش‌نمایش بازیابی</h2><p><strong><?=$preview['products']?> محصول</strong> و <strong><?=$preview['files']?> فایل محلی</strong> در این نسخه وجود دارد. کتابخانهٔ فعلی همین پروژه جایگزین می‌شود.</p><p>ابتدا یک بک‌آپ از وضعیت فعلی گرفته می‌شود. بازیابی، ارسال و همگام‌سازی خودکار را متوقف می‌کند.</p><form method="post"><input type="hidden" name="backup" value="<?=bk_h($preview['id'])?>"><button name="action" value="restore">تأیید نهایی و بازیابی</button></form></section><?php endif;?>
<div class="bk-layout"><section class="bk-card bk-versions"><div class="bk-section-head"><div><span class="bk-eyebrow">آرشیو پروژه</span><h2>نسخه‌های بک‌آپ</h2></div><span class="bk-count"><?=count($versions)?> نسخه</span></div><p class="bk-muted">نسخه را دانلود کنید یا پیش از بازیابی، محتوای آن را بررسی کنید.</p>
<?php if(!$versions):?><div class="bk-empty"><span>▣</span><h3>هنوز نسخه‌ای ندارید</h3><p>با «ساخت بک‌آپ دستی» اولین نسخهٔ امن پروژه را ذخیره کنید.</p></div><?php endif;?>
<?php foreach($versions as $item):?><article class="bk-version"><div class="bk-version-icon" aria-hidden="true">▤</div><div class="bk-version-info"><strong><?=bk_h(formatPersianDate($item['at'],'Y/m/d H:i'))?></strong><small><?=number_format($item['bytes']/1024)?> KB · JSON</small><code><?=bk_h($item['id'])?></code></div><div class="bk-version-actions"><a href="?project=<?=rawurlencode($pid)?>&download=<?=rawurlencode($item['id'])?>">دانلود ↓</a><form method="post"><input type="hidden" name="backup" value="<?=bk_h($item['id'])?>"><button name="action" value="preview">پیش‌نمایش بازیابی</button></form></div></article><?php endforeach;?></section>
<aside class="bk-sidebar"><section class="bk-card"><span class="bk-eyebrow">مرحلهٔ ۱ از ۲</span><h2>بازیابی فایل دانلودشده</h2><p>فایل همین پروژه را انتخاب کنید؛ ابتدا اعتبار و محتوای آن بررسی می‌شود.</p><form method="post" enctype="multipart/form-data"><label class="bk-upload">فایل بک‌آپ (JSON)<input type="file" name="backup_file" accept="application/json,.json" required><small>حداکثر ۳۲ مگابایت</small></label><button name="action" value="upload">بررسی فایل و پیش‌نمایش</button></form></section><section class="bk-card bk-scope"><h2>محدودهٔ بازیابی</h2><h3>در این نسخه ذخیره می‌شود</h3><p>محصولات، موجودی، توضیحات و تصاویر محلی ارجاع‌شده در کتابخانه.</p><h3>خارج از این نسخه</h3><p>حساب کاربران، دسترسی‌ها، پرداخت‌ها، تنظیمات، صف‌های ارسال، گزارش‌ها، مرکز داده و داده‌های سئو/VM؛ همچنین تصاویر خارجی و فایل‌های بدون ارجاع.</p><p class="bk-legacy">در فایل‌های قدیمی، تصاویر جاسازی نشده‌اند و باید همچنان روی هاست موجود باشند.</p></section></aside></div>
<footer class="bk-footer">هر نسخه فقط برای پروژهٔ خودش معتبر است. پیش‌نمایش، اطلاعات فعلی را تغییر نمی‌دهد.</footer></main></body></html>
